25	import org.springframework.samples.petclinic.model.Owner;
26	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
27	
28	/**
29	 * Derives an owner's {@code identityKey}: the SHA-256 hex of
30	 * {@code normalizedTelephone|lowerEmail|soundex(lastName)}. All duplicate detection is
31	 * consolidated here: two owners are the same registration only when their identity keys are
32	 * equal, and a new owner is rejected only on a full match.
33	 */
34	public final class IdentityKey {
35	
36	    private IdentityKey() {
37	    }
38	
39	    /**
40	     * The lower-case SHA-256 hex over
41	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}.
42	     */
43	    public static String of(Owner owner) {
44	        String raw = telephone(owner.getTelephone()) + "|" + email(owner.getEmail()) + "|"
45	                + Soundex.of(owner.getLastName());
46	        return sha256Hex(raw);
47	    }
48	
49	    private static String sha256Hex(String value) {
50	        try {
51	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
52	            StringBuilder sb = new StringBuilder(64);
53	            for (byte b : digest) {
54	                sb.append(String.format("%02x", b));
55	            }
56	            return sb.toString();
57	        }
58	        catch (NoSuchAlgorithmException e) {
