60	        }
61	    }
62	
63	    /** Reject with 409 when {@code candidate}'s whole identity key equals an existing owner's. */
64	    public static void rejectIfDuplicate(Owner candidate, Collection<Owner> existingOwners) {
65	        String key = of(candidate);
66	        for (Owner owner : existingOwners) {
67	            if (owner.isDeleted()) {
68	                continue;
69	            }
70	            if (key.equals(of(owner))) {
71	                throw new DuplicateTelephoneException(key);
72	            }
73	        }
74	    }
