1	package org.springframework.samples.petclinic.util;
2	
3	import java.util.Collection;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Builds an owner's {@code memberId}, formatted {@code <REGION><FY><HASH8><CHK>}: the region
9	 * (see {@link Locality}), the 2-digit fiscal year of the registration date (see {@link FiscalYear}),
10	 * the first 8 upper-case hex of SHA-256 over {@code normalizedTelephone + lastName} — the same HASH8
11	 * as the region-and-hash identity (see {@link CustomerCode}) — and a single Luhn check digit over the
12	 * digits of {@code <REGION><FY><HASH8>} (see {@link CheckDigit}). De-duplicated against existing
13	 * owners: on collision, {@code -<n>} with the smallest {@code n} of 2 or more is appended.
14	 */
15	public final class MemberId {
16	
17	    private MemberId() {
18	    }
19	
20	    /** The owner's unique {@code memberId}, de-duplicated against {@code existing}. */
21	    public static String assign(Owner owner, Collection<Owner> existing) {
22	        String base = build(owner);
23	        String id = base;
24	        int n = 1;
25	        while (isTaken(id, existing)) {
26	            id = base + "-" + (++n);
27	        }
28	        return id;
29	    }
30	
31	    /** The {@code <REGION><FY><HASH8><CHK>} member id, before de-duplication. */
32	    private static String build(Owner owner) {
33	        String regionHash = CustomerCode.assign(owner);
34	        String core = CustomerCode.region(regionHash) + fiscalYear(owner)
35	            + regionHash.substring(regionHash.indexOf('-') + 1);
36	        return core + CheckDigit.luhn(core);
37	    }
38	
39	    /** The 2-digit fiscal year of the owner's registration date. */
40	    private static String fiscalYear(Owner owner) {
41	        return String.format("%02d", Math.floorMod(FiscalYear.of(owner.getRegistrationDate()), 100));
42	    }
43	
44	    private static boolean isTaken(String id, Collection<Owner> existing) {
45	        for (Owner other : existing) {
46	            if (id.equals(other.getMemberId())) {
47	                return true;
48	            }
49	        }
50	        return false;
51	    }
52	}
