15	
16	    /** Postcode "hundreds" band (postcode / 100) -> region. */
17	    private static final Map<Integer, String> BAND_REGION =
18	        Map.of(20, "NSW", 30, "VIC", 40, "QLD");
19	
20	    private Locality() {
21	    }
22	
23	    /** The canonical region for {@code city}, or {@code "UNKNOWN"} when it is not mapped. */
24	    public static String of(String city) {
25	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
26	    }
27	
