21	            }
22	            int d = c - '0';
23	            if (dbl && (d *= 2) > 9) {
24	                d -= 9;
25	            }
26	            sum += d;
27	            dbl = !dbl;
28	        }
29	        return (10 - (sum % 10)) % 10;
30	    }
31	}
