1	package org.springframework.samples.petclinic.util;
2	
3	import java.util.Locale;
4	
5	/**
6	 * American Soundex encoding of a name: its first letter followed by up to three digits
7	 * that phonetically code the remaining consonants. Deterministic, so names that sound
8	 * alike resolve to the same code. Blank or letterless input yields {@code "0000"}.
9	 */
10	public final class Soundex {
11	
12	    /** Soundex digit for each letter A..Z; '0' marks vowels and non-coded letters. */
13	    private static final String CODES = "01230120022455012623010202";
14	
15	    private Soundex() {
16	    }
17	
18	    public static String of(String name) {
19	        String letters = (name == null ? "" : name).toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
20	        if (letters.isEmpty()) {
21	            return "0000";
22	        }
23	        StringBuilder sb = new StringBuilder().append(letters.charAt(0));
24	        char prev = codeOf(letters.charAt(0));
25	        for (int i = 1; i < letters.length() && sb.length() < 4; i++) {
26	            char code = codeOf(letters.charAt(i));
27	            if (code != '0' && code != prev) {
28	                sb.append(code);
29	            }
30	            prev = code;
31	        }
32	        while (sb.length() < 4) {
33	            sb.append('0');
34	        }
35	        return sb.toString();
36	    }
37	
38	    private static char codeOf(char letter) {
39	        return CODES.charAt(letter - 'A');
40	    }
41	}
