1	package org.springframework.samples.petclinic.util;
2	
3	import java.time.LocalDate;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Computes an owner's membership standing as a points total and the level it maps to.
9	 * Points start at 0 and accrue: +2 for a present email, +1 when the owner has no
10	 * namesakes, +2 for a household of three or more (see {@link GoldTier}), and +3 for
11	 * tenure spanning more than one elapsed fiscal year (see {@link FiscalYear}). Levels
12	 * map from points: 1 (0-1), 2 (2-3), 3 (4-5), 4 (6+).
13	 */
14	public final class Membership {
15	
16	    private Membership() {
17	    }
18	
19	    /** Total membership points for {@code owner}. */
20	    public static int points(Owner owner) {
21	        int points = 0;
22	        if (owner.getEmail() != null) {
23	            points += 2;
24	        }
25	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
26	            points += 1;
27	        }
28	        if (Boolean.TRUE.equals(owner.getHouseholdGold())) {
29	            points += 2;
30	        }
31	        if (FiscalYear.of(LocalDate.now()) - FiscalYear.of(owner.getRegistrationDate()) > 1) {
32	            points += 3;
33	        }
34	        return points;
35	    }
36	
37	    /** Membership level (1-4) for a points total. */
38	    public static int level(int points) {
39	        if (points >= 6) {
40	            return 4;
41	        }
42	        if (points >= 4) {
43	            return 3;
44	        }
45	        if (points >= 2) {
46	            return 2;
47	        }
48	        return 1;
49	    }
50	}
